    df = df.where((F.col("p.Exposure") > F.lit(0)))
    df = df.select(
        F.col("p.IDpol").alias('IDpol'),
        (F.col("p.Exposure").cast("decimal(10,6)") - (F.col("p.Exposure").cast("decimal(10,6)") % F.lit(Decimal("0.01")).cast("decimal(3,2)"))).cast("decimal(10,6)").alias('ExposureTrunc'),
        F.upper(F.ltrim(F.rtrim(F.col("p.VehBrand")))).alias('VehBrand'),
        F.when((F.upper(F.rtrim(F.col("p.VehGas"))) == F.upper(F.rtrim(F.lit('diesel')))), F.lit('D')).when((F.upper(F.rtrim(F.col("p.VehGas"))) == F.upper(F.rtrim(F.lit('regular')))), F.lit('R')).otherwise(F.lit('U')).alias('FuelCode'),
        F.when((F.col("p.DrivAge") < F.lit(25)), F.lit('18-24')).when((F.col("p.DrivAge") < F.lit(40)), F.lit('25-39')).when((F.col("p.DrivAge") < F.lit(60)), F.lit('40-59')).otherwise(F.lit('60+')).alias('AgeBand'),
    )
    return df


